//! Expected complete outputs were generated by actual current TS production functions.
//! Deterministic UUID factory is the only changed dependency; no browser/native hardware claim.
use super::*;
fn vectors() -> Value {
    serde_json::from_str(include_str!("scan_resume_reconcile_oracle.json")).unwrap()
}
fn run(case: &Value) -> Result<Prepared, String> {
    let selected: Vec<_> = case["selected"]
        .as_array()
        .unwrap()
        .iter()
        .map(|s| Selected {
            original_index: s["originalIndex"].as_u64().unwrap() as usize,
            candidate: &s["candidate"],
            observation: &s["observation"],
        })
        .collect();
    let mut generated = 0;
    prepare(
        Context {
            catalog: &case["catalog"],
            preferences: &case["preferences"],
            source_policies: case["sourcePolicies"].as_array().unwrap(),
            session_revision: "session",
            platform: "android",
            observer_profile: "fixture-v1",
        },
        &selected,
        &|channel| {
            let scope = case["scopes"]
                .as_array()
                .unwrap()
                .iter()
                .find(|s| s["sourceId"] == channel["sourceId"])
                .unwrap();
            Ok((
                scope["ambiguousProviderKeys"]
                    .as_array()
                    .unwrap()
                    .contains(&json!(provider(channel)?)),
                scope["ambiguousMetadataKeys"]
                    .as_array()
                    .unwrap()
                    .contains(&json!(metadata(channel)?)),
            ))
        },
        &mut || {
            generated += 1;
            format!("00000000-0000-4000-8000-{generated:012}")
        },
        &mut || Ok(()),
    )
}
#[test]
fn actual_ts_complete_publication_output_parity() {
    let oracle = vectors();
    assert_eq!(oracle["cases"].as_array().unwrap().len(), 9);
    for case in oracle["cases"].as_array().unwrap() {
        let unchanged = case.clone();
        let prepared = run(case).unwrap_or_else(|e| panic!("{}: {e}", case["name"]));
        let actual = json!({"schemaVersion":1,"catalogPatch":prepared.catalog_patch,"nextPreferences":prepared.next_preferences,"incomingHealth":prepared.incoming_health});
        assert_eq!(
            actual, case["expected"],
            "complete TS oracle {}",
            case["name"]
        );
        let batch = crate::scan_batch::Batch {
            schema_version: 1,
            catalog_patch: prepared.catalog_patch,
            authorized_sources: prepared.next_preferences["sources"]
                .as_array()
                .unwrap()
                .clone(),
            next_preferences: prepared.next_preferences,
            incoming_health: prepared.incoming_health,
            expected_catalog_revision: "1".into(),
            expected_health_revision: "1".into(),
            scan_checkpoint: None,
            expected_checkpoint_revision: None,
        };
        let expanded = crate::scan_batch::expand(&batch, &case["catalog"], || Ok(())).unwrap();
        assert_eq!(
            expanded, case["expectedCatalog"],
            "all unselected rows/preferences retained {}",
            case["name"]
        );
        assert_eq!(case, &unchanged);
        assert_eq!(
            prepared.mappings.len(),
            case["selected"].as_array().unwrap().len()
        );
        for mapping in prepared.mappings {
            assert!(batch
                .incoming_health
                .iter()
                .any(|h| h["channelId"] == mapping.channel_id));
            assert!(case["selected"]
                .as_array()
                .unwrap()
                .iter()
                .any(|s| s["originalIndex"] == mapping.original_index));
        }
    }
}
#[test]
fn full_review_ambiguity_outside_selected_page_preserves_existing_variant() {
    let oracle = vectors();
    let case = oracle["cases"]
        .as_array()
        .unwrap()
        .iter()
        .find(|c| c["name"] == "full-review-ambiguity-outside-selected-page")
        .unwrap();
    let prepared = run(case).unwrap();
    assert_eq!(prepared.catalog_patch.base_channel_count, 1);
    assert_eq!(prepared.catalog_patch.final_channel_count, 3);
    assert!(!prepared
        .catalog_patch
        .channels
        .iter()
        .any(|c| c["id"] == "old-same"));
}
#[test]
fn unknown_source_changed_identity_grant_and_negative_never_manufacture_publication() {
    let oracle = vectors();
    for fault in [
        "source",
        "fingerprint",
        "session",
        "negative",
        "grant",
        "observation",
        "duplicate-index",
    ] {
        let mut case = oracle["cases"][0].clone();
        match fault {
            "source" => case["selected"][0]["candidate"]["sourceId"] = json!("foreign"),
            "fingerprint" => {
                case["selected"][0]["candidate"]["sourceFingerprint"] = json!("foreign")
            }
            "session" => case["selected"][0]["candidate"]["sessionRevision"] = json!("obsolete"),
            "negative" => {
                case["selected"][0]["observation"]["verdict"] = json!("TemporaryUnavailable");
                case["selected"][0]["observation"]["evidence"] = json!({"kind":"network-failure"});
            }
            "grant" => {
                case["selected"][0]["candidate"]["channel"]["urls"][0] =
                    json!("http://media.fixture.invalid/private-grant.m3u8")
            }
            "observation" => case["selected"][0]["observation"]["fingerprint"] = json!("foreign"),
            "duplicate-index" => {
                let row = case["selected"][0].clone();
                case["selected"].as_array_mut().unwrap().push(row);
            }
            _ => unreachable!(),
        }
        assert!(run(&case).is_err(), "{fault}");
    }
}
#[test]
fn generated_collision_cancellation_and_64_bound_are_refused() {
    let oracle = vectors();
    let mut case = oracle["cases"][4].clone();
    let rows: Vec<_> = case["selected"]
        .as_array()
        .unwrap()
        .iter()
        .map(|s| Selected {
            original_index: s["originalIndex"].as_u64().unwrap() as usize,
            candidate: &s["candidate"],
            observation: &s["observation"],
        })
        .collect();
    // Force UUID generation for both rows using genuine whole-review ambiguity.
    assert!(prepare(
        Context {
            catalog: &case["catalog"],
            preferences: &case["preferences"],
            source_policies: case["sourcePolicies"].as_array().unwrap(),
            session_revision: "session",
            platform: "android",
            observer_profile: "fixture-v1"
        },
        &rows,
        &|_| Ok((true, true)),
        &mut || "same-id".into(),
        &mut || Ok(())
    )
    .is_err());
    assert_eq!(
        prepare(
            Context {
                catalog: &case["catalog"],
                preferences: &case["preferences"],
                source_policies: case["sourcePolicies"].as_array().unwrap(),
                session_revision: "session",
                platform: "android",
                observer_profile: "fixture-v1"
            },
            &rows,
            &|_| Ok((false, false)),
            &mut || "id".into(),
            &mut || Err("canceled".into())
        )
        .err()
        .unwrap(),
        "canceled"
    );
    let repeated = case["selected"][0].clone();
    case["selected"] = Value::Array(vec![repeated; 65]);
    assert!(run(&case).is_err());
}
